import {mountGuidedWeekly} from './workshop-repair-guided-weekly-ui.mjs';
import {mountGuidedReviews} from './workshop-repair-guided-review-ui.mjs';
import {interventionProgress,guidedReviewPlan} from './workshop-repair-guided-progress.mjs';
import {loadGuidedHistory,guidedWeaknesses,guidedResultScore} from './workshop-repair-guided-history.mjs';
import {caseInfo} from './workshop-content.mjs';
import {alternate} from './workshop-challenges.mjs';
export function mountGuidedHistory({language,available,hidden,launch}){
 const root=document.createElement('section');root.id='guidedRepairHistory';root.className='challenge-panel';document.querySelector('main').append(root);const t=(es,en)=>language()==='es'?es:en,local=x=>x[language()],name=g=>local(g.id==='primary'?caseInfo[g.kind].fix:alternate[g.kind].fix);
 const launchReview=g=>{let rows=[];try{rows=loadGuidedHistory(localStorage);}catch{return;}const plan=guidedReviewPlan(rows,g.kind,g.id);launch({...g,plan,fault:plan.fault});};
 const weekly=mountGuidedWeekly({language,host:root,hidden,available,interventionName:name,launch:launchReview});
 const calendar=mountGuidedReviews({language,host:root,hidden,available,interventionName:name,launch:launchReview,onGoalChange:()=>weekly.render()});
 function render(){root.replaceChildren();root.hidden=hidden();if(root.hidden){calendar.render();weekly.render();return;}const add=(tag,text,host=root)=>{const n=document.createElement(tag);n.textContent=text;host.append(n);return n;};add('h2',t('Historial de decisiones guiadas','Guided repair history'));let rows=[];try{rows=loadGuidedHistory(localStorage);}catch{document.querySelector('#guidedRepairCalendar').hidden=true;document.querySelector('#guidedRepairWeekly').hidden=true;add('p',t('No se pudo leer el historial. Los datos guardados no se han modificado.','Could not read history. Saved data has not been modified.'));return;}calendar.render(rows);weekly.render(rows);add('p',t('Últimas 100 prácticas guiadas completadas, guardadas en este navegador. No alteran notas de examen ni reparaciones verificadas. La racha guiada se muestra en su calendario. Los órdenes alternativos útiles cuentan como aciertos.','Latest 100 completed guided practices, saved in this browser. They do not change exam grades or verified repairs. The guided streak is shown in its calendar. Useful alternative orders count as correct choices.'));if(!rows.length){add('p',t('Completa una práctica guiada para descubrir qué intervenciones debes repasar.','Complete a guided practice to discover which interventions need review.'));return;}
 add('p',rows.length+t(' prácticas · primera nota ',' practices · first score ')+guidedResultScore(rows[0])+'/100 · '+t('última ','latest ')+guidedResultScore(rows.at(-1))+'/100');add('h3',t('Intervenciones con más errores','Interventions with the most mistakes'));add('p',t('Un error significa aplicar una corrección innecesaria o repetir una ya realizada. Se ordenan por número de errores; compara también el total de elecciones. Los repasos se adaptan a las tres últimas prácticas de cada intervención.','An error means applying an unnecessary correction or repeating one already made. Ranked by error count; also compare the number of choices. Reviews adapt to the latest three practices for each intervention.'));
 for(const g of guidedWeaknesses(rows)){const card=add('article','');card.className='repair-progress-card';add('h4',name(g),card);add('p',g.wrong+'/'+g.total+t(' elecciones innecesarias · ',' unnecessary choices · ')+g.hints+t(' pistas usadas en estas decisiones',' hints used for these decisions'),card);const progress=interventionProgress(rows,g.kind,g.id),plan=guidedReviewPlan(rows,g.kind,g.id);
 const chart=add('figure','',card);chart.className='intervention-chart';add('figcaption',t('Aciertos por intervención · escala 0–100%','Useful choices per intervention · 0–100% scale'),chart);
 for(const [key,label] of [['first',t('Primeras prácticas','First practices')],['reviews',t('Repasos recientes','Recent reviews')]]){const data=progress[key],row=add('div','',chart);row.className='intervention-chart-row';add('strong',label,row);const track=add('div','',row);track.className='intervention-chart-track';track.setAttribute('aria-hidden','true');const bar=add('span','',track);bar.style.width=(data.percent??0)+'%';bar.className=key;add('span',data.percent===null?t('Sin datos aún','No data yet'):data.percent+'% · '+data.correct+'/'+data.total+' · '+data.sessions+(data.sessions===1?t(' práctica',' practice'):t(' prácticas',' practices')),row);}
 add('p',t('Primeras: hasta 3 prácticas iniciales. Repasos: las últimas 3. Son grupos distintos; cada elección cuenta, incluso las repetidas.','First: up to 3 initial practices. Reviews: the latest 3. These are separate groups; every choice counts, including repeated choices.'),chart);
 add('p',t('Próximo reto: ','Next challenge: ')+([null,t('1 · Un fallo','1 · Single fault'),t('2 · Fallos combinados','2 · Combined faults'),t('3 · Fallo intermitente','3 · Intermittent fault')][plan.level])+' · '+plan.clean+'/3 '+t('prácticas recientes sin errores ni pistas.','recent practices without errors or hints.'),card);
 add('p',t('Tres prácticas seguidas sin errores ni pistas en esta intervención desbloquean fallos combinados; tres así en niveles avanzados desbloquean intermitentes. Un error o pista vuelve al nivel de un fallo. En intermitentes, recorre el tiempo para observar la pérdida y el retorno de la señal.','Three consecutive practices without errors or hints on this intervention unlock combined faults; three such advanced practices unlock intermittent faults. An error or hint returns to single faults. For intermittent faults, scrub time to observe the signal disappearing and returning.'),card);
 const b=add('button',g.wrong?t('Repasar esta dificultad','Review this difficulty'):t('Reforzar esta intervención','Reinforce this intervention'),card);b.dataset.guidedPractice=g.key;b.disabled=!available();b.onclick=()=>launch({...g,fault:plan.fault,plan});}
 if(!available())add('p',t('Abre un examen completado para practicar en los bancos 3D.','Open a completed exam to practise in the 3D benches.'));const details=add('details','');add('summary',t('Ver resultados y decisiones','View results and decisions'),details);for(const g of [...rows].reverse()){const card=add('article','',details);add('h4',new Date(g.finished).toLocaleString(language(),{timeZone:'America/Bogota'})+' · '+local(caseInfo[g.user.kind].title)+' · '+guidedResultScore(g)+'/100',card);const list=add('ol','',card);for(const r of g.rounds)add('li',name({kind:g.user.kind,id:r.id})+' · '+(r.useful?t('Útil','Useful'):t('Innecesaria','Unnecessary'))+(r.hint?t(' · con pista',' · with hint'):''),list);}
 }
 return {render};
}
